const crypto = require("crypto");
const AuthChallenge = require("../../models/AuthChallenge");
const { hitAll } = require("./authRateLimit");
const delivery = require("./otpDelivery");

/**
 * Six-digit sign-in codes, by text or email.
 *
 * What protects them:
 *  - generated by crypto.randomInt, never Math.random;
 *  - stored only as an HMAC bound to channel + address, compared in constant time;
 *  - valid for 10 minutes, for one sign-in, and for 5 guesses;
 *  - a new code supersedes the old one, so only the latest works;
 *  - sending is limited per address, per IP and per day across the whole site
 *    (the daily cap bounds what SMS pumping could ever cost), and guessing is
 *    limited per address and per IP across codes, so rotating codes does not
 *    buy more guesses;
 *  - the answer to "send a code" is the same whether or not an account exists.
 */

const CODE_TTL_MS = 10 * 60 * 1000;
const MAX_ATTEMPTS = 5;
const MINUTE = 60 * 1000;
const HOUR = 60 * MINUTE;
const DAY = 24 * HOUR;

class OtpError extends Error {
  constructor(code, extra = {}) {
    super(code);
    this.code = code;
    Object.assign(this, extra);
  }
}

function secret(env = process.env) {
  const base = String(env.OTP_HASH_SECRET || env.JWT_SECRET || "");
  if (!base) throw new Error("OTP_HASH_SECRET or JWT_SECRET is required");
  return `${base}:auth-otp:v1`;
}

/* Purpose is part of the binding: a sign-in code is never a password-reset code. */
function hashCode(channel, target, code, env, purpose = "auth") {
  return crypto.createHmac("sha256", secret(env)).update(`${purpose}|${channel}|${target}|${code}`).digest("hex");
}

function sameHash(a, b) {
  const left = Buffer.from(String(a), "hex");
  const right = Buffer.from(String(b), "hex");
  return left.length === right.length && left.length > 0 && crypto.timingSafeEqual(left, right);
}

function newCode() {
  return String(crypto.randomInt(0, 1000000)).padStart(6, "0");
}

function hashIp(ip) {
  return ip ? crypto.createHash("sha256").update(`ip|${ip}`).digest("hex").slice(0, 32) : "";
}

function sendRules(channel, target, ipHash, env = process.env) {
  const rules = [
    { name: "cooldown", key: `send:${channel}:${target}:cool`, limit: 1, windowMs: 30 * 1000 },
    { name: "target_hour", key: `send:${channel}:${target}:h`, limit: 5, windowMs: HOUR },
    { name: "target_day", key: `send:${channel}:${target}:d`, limit: channel === "sms" ? 10 : 15, windowMs: DAY },
  ];
  if (ipHash) {
    rules.push(
      { name: "ip_hour", key: `send:${channel}:ip:${ipHash}:h`, limit: channel === "sms" ? 10 : 20, windowMs: HOUR },
      { name: "ip_day", key: `send:${channel}:ip:${ipHash}:d`, limit: channel === "sms" ? 30 : 60, windowMs: DAY }
    );
  }
  if (channel === "sms") {
    const cap = Number(env.OTP_SMS_DAILY_CAP) > 0 ? Number(env.OTP_SMS_DAILY_CAP) : 300;
    rules.push({ name: "global_day", key: "send:sms:global:d", limit: cap, windowMs: DAY });
  }
  return rules;
}

/**
 * Send a code. Returns what the screen needs; never says whether an account
 * exists. `deliver` is injectable so tests never send anything.
 */
async function startChallenge({ channel, target, purpose = "auth", consent = null, ip = "", env = process.env, deliver = null, ttlMs = CODE_TTL_MS }) {
  const ipHash = hashIp(ip);
  const limited = await hitAll(sendRules(channel, target, ipHash, env).map((rule) => ({ ...rule, key: `${purpose}:${rule.key}` })));
  if (!limited.allowed) {
    throw new OtpError("RATE_LIMITED", { retryAfterSeconds: limited.retryAfterSeconds });
  }

  const useVerify = channel === "sms" && Boolean(delivery.verifyServiceSid(env));
  const code = useVerify ? null : newCode();

  // Deliver first: a code that never left must not supersede one that did.
  if (deliver) await deliver({ channel, target, code });
  else if (channel === "sms") await (useVerify ? delivery.startVerify(target, { env }) : delivery.sendSmsCode(target, code, { env }));
  else await delivery.sendEmailCode(target, code);

  const now = new Date();
  await AuthChallenge.updateMany(
    { channel, target, purpose, consumedAt: null, supersededAt: null },
    { $set: { supersededAt: now } }
  );
  await AuthChallenge.create({
    channel,
    target,
    purpose,
    provider: useVerify ? "twilio_verify" : "local",
    codeHash: code ? hashCode(channel, target, code, env, purpose) : "",
    maxAttempts: MAX_ATTEMPTS,
    expiresAt: new Date(now.getTime() + ttlMs),
    ipHash,
    consent: { transactional: Boolean(consent?.transactional), marketing: Boolean(consent?.marketing) },
  });

  return { resendAfterSeconds: 30, expiresInSeconds: ttlMs / 1000 };
}

/**
 * Check a code. Resolves when it is right and claims it, so it can never be
 * used again; throws OtpError otherwise.
 */
async function verifyChallenge({ channel, target, code, purpose = "auth", ip = "", env = process.env, checkRemote = null }) {
  const clean = String(code || "").replace(/\D/g, "");
  if (clean.length !== 6) throw new OtpError("INVALID_CODE", { attemptsLeft: null });

  const ipHash = hashIp(ip);
  const limited = await hitAll([
    { name: "verify_target", key: `${purpose}:verify:${channel}:${target}:h`, limit: 15, windowMs: HOUR },
    ...(ipHash ? [{ name: "verify_ip", key: `verify:ip:${ipHash}:h`, limit: 40, windowMs: HOUR }] : []),
  ]);
  if (!limited.allowed) throw new OtpError("RATE_LIMITED", { retryAfterSeconds: limited.retryAfterSeconds });

  const challenge = await AuthChallenge.findOne({ channel, target, purpose, consumedAt: null, supersededAt: null })
    .sort({ createdAt: -1 })
    .lean();
  if (!challenge || challenge.expiresAt.getTime() <= Date.now()) throw new OtpError("CODE_EXPIRED");
  if (challenge.attempts >= challenge.maxAttempts) throw new OtpError("CODE_EXPIRED");

  let correct;
  if (challenge.provider === "twilio_verify") {
    correct = checkRemote ? await checkRemote({ target, code: clean }) : await delivery.checkVerify(target, clean, { env });
  } else {
    correct = sameHash(challenge.codeHash, hashCode(channel, target, clean, env, purpose));
  }

  if (!correct) {
    const updated = await AuthChallenge.findOneAndUpdate(
      { _id: challenge._id },
      { $inc: { attempts: 1 } },
      { new: true }
    ).lean();
    const attemptsLeft = Math.max(0, updated.maxAttempts - updated.attempts);
    if (attemptsLeft === 0) throw new OtpError("CODE_EXPIRED");
    throw new OtpError("INVALID_CODE", { attemptsLeft });
  }

  // One sign-in per code, even if two requests arrive together.
  const claimed = await AuthChallenge.updateOne(
    { _id: challenge._id, consumedAt: null },
    { $set: { consumedAt: new Date() } }
  );
  if (claimed.modifiedCount !== 1) throw new OtpError("CODE_EXPIRED");
  return { purpose: challenge.purpose, consent: challenge.consent || {} };
}

module.exports = {
  CODE_TTL_MS,
  MAX_ATTEMPTS,
  OtpError,
  hashIp,
  newCode,
  startChallenge,
  verifyChallenge,
};
